def compact(batches):
    """Remove empty batches (empty lists) from `batches` in place.

    Returns the number of batches removed. Surviving batches keep their order.
    """
    removed = 0
    i = 0
    while i < len(batches):
        if not batches[i]:
            del batches[i]
            removed += 1
        else:
            i += 1
    return removed

