def flatten(value):
    """Flatten nested lists and tuples into a flat list of leaves.

    Strings, dicts and None are leaves. Empty containers contribute nothing.
    """
    if isinstance(value, list) or isinstance(value, tuple):
        if not value:
            return []  # Empty containers should contribute nothing
        out = []
        for item in value:
            out.extend(flatten(item))
        return out
    return [value]  # Single items are leaves

